-- Seed HHAX Future State Program data
CREATE TEMP TABLE _ids (k text PRIMARY KEY, v uuid NOT NULL) ON COMMIT DROP;
WITH ins AS (INSERT INTO public.programs (name, description, status) VALUES ('HHAX Future State Program', 'Four-workshop assessment for SRE, Data Center Ops, and MSP transformation', 'active') RETURNING id) INSERT INTO _ids(k,v) SELECT 'prog-1', id FROM ins;
WITH ins AS (INSERT INTO public.workstreams (program_id, name, description, display_order) SELECT v, 'Workshop 1: Current State & Business Priorities', 'Understand business priorities, customer impact, current operating model, and pain points', 1 FROM _ids WHERE k='prog-1' RETURNING id) INSERT INTO _ids(k,v) SELECT 'ws-1', id FROM ins;
